import { lazy, Suspense } from 'react';
import { BrowserRouter, Routes, Route } from 'react-router-dom';

// TODO: lazy import HomePageLazy and AboutPageLazy
// (define them as inline components below for this exercise)

function HomePage() {
  return <h1 data-testid="home">Home</h1>;
}

function AboutPage() {
  return <h1 data-testid="about">About</h1>;
}

// For this exercise, wrap them with lazy:
const HomePageLazy = lazy(() => Promise.resolve({ default: HomePage }));
const AboutPageLazy = lazy(() => Promise.resolve({ default: AboutPage }));

export default function App() {
  return (
    <BrowserRouter>
      {/* TODO: wrap Routes in Suspense with loading fallback */}
      <Routes>
        <Route path="/" element={<HomePageLazy />} />
        <Route path="/about" element={<AboutPageLazy />} />
      </Routes>
    </BrowserRouter>
  );
}
